<?php
/** ChatGPT coordinates external publishing tools; a queued job is never a delivery receipt. */
class AiSocial {
    private $store;
    public function __construct($store){$this->store=$store;}
    public static function route($settings,$platform){$key=$platform==='instagram_story'?'instagram':$platform;return in_array($key,['telegram','instagram'],true)&&($settings['connections'][$key]['proxy']['bypass_method']??'')==='chatgpt';}
    public static function allowed($mode='view'){AiAccess::need('calendar',$mode);}
    public function enqueue($project,$input,$actor='scheduler'){
        $platform=$input['platform']??'';$kind=$input['kind']??'post';if(!in_array($platform,['telegram','instagram'],true)||!self::route($project['settings'],$platform))throw new RuntimeException('روش ChatGPT برای این کانال فعال نیست.');
        if(!in_array($kind,$platform==='telegram'?['post']:['post','story','reel','carousel'],true))throw new RuntimeException('نوع انتشار معتبر نیست.');
        $request=$input['request_id']??'';$caption=$input['caption']??'';$media=$input['media']??[];$at=$input['scheduled_at']??time();
        if(!is_string($request)||!preg_match('/^[a-zA-Z0-9_.:-]{8,150}$/D',$request)||!is_string($caption)||mb_strlen($caption)>10000||!is_array($media)||count($media)>10||!is_int($at)||$at<0||$at>time()+366*86400)throw new RuntimeException('محتوا یا زمان انتشار معتبر نیست.');
        foreach($media as $url)if(!is_string($url)||!filter_var($url,FILTER_VALIDATE_URL)||strtolower(parse_url($url,PHP_URL_SCHEME)??'')!=='https'||isset(parse_url($url)['user']))throw new RuntimeException('فایل انتشار باید آدرس عمومی HTTPS داشته باشد.');
        if($caption===''&&!$media||$platform==='instagram'&&!$media)throw new RuntimeException('محتوای انتشار کامل نیست.');
        $productId=$input['product_id']??'';if($productId!==''){$p=AiContent::find($project,['product_id'=>$productId]);if(WebsiteCatalogSync::pendingApprovalPhotos($p,true))throw new RuntimeException('تصویر محصول هنوز تأیید نشده است.');$approved=array_map([AiData::class,'media'],WebsiteCatalogSync::photos($p));if(!empty($p['social_image'])&&WebsiteCatalogSync::imageApproved($p,$p['social_image']))$approved[]=AiData::media($p['social_image']);if(array_diff($media,$approved))throw new RuntimeException('رسانه باید از تصاویر تأییدشدهٔ همین محصول انتخاب شود.');}
        $definition=['destination'=>$project['settings']['connections'][$platform]['chatgpt_destination']??'','platform'=>$platform,'kind'=>$kind,'caption'=>$caption,'media'=>array_values($media),'scheduled_at'=>$at,'product_id'=>$productId,'schedule_id'=>$input['schedule_id']??''];$hash=hash('sha256',json_encode($definition));$id=substr(hash('sha256',$project['id'].'|'.$request),0,32);
        return $this->store->transaction(static function(&$s)use($id,$definition,$hash,$project,$actor){$old=$s['social_jobs'][$id]??null;if($old){if($old['hash']!==$hash)throw new RuntimeException('شناسهٔ انتشار با محتوای متفاوت تکرار شده است.');return ['id'=>$id,'state'=>$old['state'],'queued'=>true];}$s['social_jobs'][$id]=$definition+['id'=>$id,'project'=>$project['id'],'state'=>'queued','hash'=>$hash,'created'=>time(),'by'=>$actor];return ['id'=>$id,'state'=>'queued','queued'=>true];});
    }
    public function create($project,$grant,$args){AiAccess::need('approve','use');AiAccess::scope($grant,'social.write');self::allowed('use');AiAccess::write();return $this->enqueue($project,$args,$grant['username']);}
    public function jobs($project){self::allowed();$s=$this->store->read();$rows=[];foreach($s['social_jobs']??[] as $j)if($j['project']===$project['id']){$row=$j;unset($row['hash'],$row['lease_hash']);$row['due']=$j['scheduled_at']<=time();$rows[]=$row;}return array_slice(array_reverse($rows),0,200);}
    public function claim($project,$grant,$id,$scheduleExternally=false){AiAccess::scope($grant,'social.write');self::allowed('use');AiAccess::write();$lease=bin2hex(random_bytes(32));return $this->store->transaction(static function(&$s)use($project,$grant,$id,$lease,$scheduleExternally){if(!is_string($id)||!isset($s['social_jobs'][$id]))throw new RuntimeException('انتشار یافت نشد.');$j=&$s['social_jobs'][$id];if(!$j||$j['project']!==$project['id']||$j['state']!=='queued'||(!$scheduleExternally&&$j['scheduled_at']>time())||!AiSocial::route($project['settings'],$j['platform']))throw new RuntimeException('انتشار آمادهٔ دریافت نیست.');$j['state']='claimed';$j['lease_hash']=hash('sha256',$lease);$j['lease_until']=time()+900;$j['claimed_by']=$grant['owner'];return ['job'=>array_diff_key($j,['hash'=>1,'lease_hash'=>1]),'lease'=>$lease,'instruction'=>'Publish with your separately connected social tool, then acknowledge the actual provider receipt. Never claim delivery from queue acceptance alone.'];});}
    public function ack($project,$grant,$args){AiAccess::scope($grant,'social.write');self::allowed('use');AiAccess::write();$id=$args['id']??'';$lease=$args['lease']??'';$state=$args['state']??'';$receipt=$args['receipt']??'';
        if(!in_array($state,['published','scheduled_external','failed','uncertain'],true)||!is_string($receipt)||strlen($receipt)>2000||(in_array($state,['published','scheduled_external'],true)&&trim($receipt)===''))throw new RuntimeException('رسید واقعی سرویس برای ثبت انتشار لازم است.');
        return $this->store->transaction(static function(&$s)use($id,$lease,$state,$receipt,$project,$grant){if(!is_string($id)||!isset($s['social_jobs'][$id]))throw new RuntimeException('انتشار یافت نشد.');$j=&$s['social_jobs'][$id];if(!$j||$j['project']!==$project['id']||!is_string($lease)||!hash_equals($j['lease_hash']??'',hash('sha256',$lease))||($j['claimed_by']??'')!==$grant['owner'])throw new RuntimeException('اجازهٔ ثبت نتیجهٔ این انتشار وجود ندارد.');if(in_array($j['state'],['published','scheduled_external','failed','uncertain'],true)&&!($j['state']==='scheduled_external'&&$state==='published')){if($j['state']===$state&&($j['receipt']??'')===$receipt)return ['id'=>$id,'state'=>$state];throw new RuntimeException('نتیجه قبلاً ثبت شده است.');}if(!in_array($j['state'],['claimed','scheduled_external'],true))throw new RuntimeException('وضعیت انتشار معتبر نیست.');$j['state']=$state;$j['receipt']=$receipt;$j['verification']='external_reported';$j['finished']=time();return ['id'=>$id,'state'=>$state,'verification'=>'external_reported'];});
    }
    public function cancel($project,$id){self::allowed('use');$this->store->transaction(static function(&$s)use($project,$id){if(!is_string($id)||!isset($s['social_jobs'][$id]))throw new RuntimeException('انتشار یافت نشد.');$j=&$s['social_jobs'][$id];if(!$j||$j['project']!==$project['id']||$j['state']!=='queued')throw new RuntimeException('فقط انتشار در صف قابل لغو است.');$j['state']='cancelled';});}
    public function plan($project,$grant,$args){
        $dir=sys_get_temp_dir().'/maarksho-website-'.substr(hash('sha256',dirname(__DIR__,2)),0,16);if(!is_dir($dir))mkdir($dir,0700,true);$lock=fopen($dir.'/'.hash('sha256',$project['id']).'.lock','c');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('قفل تقویم آماده نیست.');
        try{$fresh=getCurrentProject($project['id'],true);if(!$fresh)throw new RuntimeException('پروژه یافت نشد.');return $this->planUnlocked($fresh,$grant,$args);}finally{flock($lock,LOCK_UN);fclose($lock);}
    }
    private function planUnlocked($project,$grant,$args){
        AiAccess::scope($grant,'social.write');self::allowed('use');AiAccess::write();
        $request=$args['request_id']??'';$items=$args['items']??null;
        if(!is_string($request)||!preg_match('/^[A-Za-z0-9_-]{8,100}$/D',$request)||!is_array($items)||!$items||count($items)>30)throw new RuntimeException('برنامه باید شناسهٔ یکتا و ۱ تا ۳۰ محتوا داشته باشد.');
        $patch=[];$ids=[];
        foreach($items as $i=>$item){$platform=$item['platform']??'';$kind=$item['kind']??'post';$at=$item['scheduled_at']??0;$caption=$item['caption']??'';$media=$item['media']??[];
            if(!in_array($platform,['telegram','instagram'],true)||!self::route($project['settings'],$platform)||!in_array($kind,$platform==='telegram'?['post']:['post','story','reel','carousel'],true)||!is_int($at)||$at<time()||$at>time()+366*86400||!is_string($caption)||mb_strlen($caption)>10000||!is_array($media)||count($media)>10)throw new RuntimeException('ردیف برنامه یا زمان آینده معتبر نیست.');
            foreach($media as $url)if(!is_string($url)||!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https')throw new RuntimeException('آدرس رسانه HTTPS لازم است.');
            if($platform==='instagram'&&!$media)throw new RuntimeException('رسانهٔ اینستاگرام لازم است.');
            $productId=(string)($item['product_id']??'');$product=$productId!==''?AiContent::find($project,['product_id'=>$productId]):null;
            $id=substr(hash('sha256',$project['id'].'|plan|'.$request.'|'.$i),0,32);$ids[]=$id;
            $row=['id'=>$id,'productId'=>$productId,'productName'=>$product['name']??'برنامهٔ ChatGPT','platform'=>$platform==='instagram'&&$kind==='story'?'instagram_story':$platform,'caption'=>$caption,'mediaUrl'=>implode(',',$media).'|'.$kind,'scheduledAt'=>$at,'status'=>'pending','approvalStatus'=>'pending','created_at'=>time()];
            foreach($project['schedules']??[] as $old)if((string)$old['id']===$id){foreach(['platform','caption','mediaUrl','scheduledAt','productId'] as $key)if(($old[$key]??'')!==$row[$key])throw new RuntimeException('برنامه با این شناسه و محتوای متفاوت از قبل وجود دارد.');continue 2;}
            $patch[]=$row;
        }
        if($patch&&!saveProject($project,null,$patch))throw new RuntimeException('ثبت تقویم انجام نشد.');return ['schedule_ids'=>$ids,'created'=>count($patch),'approval_status'=>'pending','note'=>'برنامه در تقویم ثبت شد و تا تأیید عادی تقویم ارسال نمی‌شود.'];
    }
    public function reconcile($project){$s=$this->store->read();$patch=[];foreach($project['schedules']??[] as $schedule)foreach($s['social_jobs']??[] as $j)if($j['project']===$project['id']&&$j['schedule_id']!==''&&(string)$j['schedule_id']===(string)$schedule['id']&&in_array($j['state'],['published','scheduled_external','failed','uncertain'],true)){$status=$j['state']==='published'?'completed':($j['state']==='failed'?'failed':($j['state']==='scheduled_external'?'scheduled_external':'awaiting_chatgpt'));if($schedule['status']!==$status){$schedule['status']=$status;$patch[]=$schedule;}}if($patch)saveProject($project,null,$patch);}
    public static function legacy($product,$platform,$settings,$caption,$media,$at=null,$scheduleId='',$kind='post',$project=null){
        require_once __DIR__.'/Bootstrap.php';$project=$project?:getCurrentProject();if(!$project)throw new RuntimeException('پروژهٔ انتشار یافت نشد.');
        $urls=is_array($media)?$media:array_values(array_filter(explode(',',explode('|',(string)$media)[0])));$urls=array_map([AiData::class,'media'],$urls);
        if(is_string($media)&&preg_match('/\|(story|reel|carousel)$/',$media,$match))$kind=$match[1];
        $date=is_int($at)&&$at>0?$at:time();$request=$scheduleId!==''?'schedule-'.$scheduleId:'send-'.hash('sha256',json_encode([$product['id']??'', $platform,$caption,$urls,$at]));
        $linkedId='';foreach($project['products']??[] as $candidate)if((string)($candidate['id']??'')===(string)($product['id']??'')){$linkedId=(string)$candidate['id'];break;}
        return (new self(new AiStore()))->enqueue($project,['request_id'=>$request,'platform'=>$platform==='instagram_story'?'instagram':$platform,'kind'=>$platform==='instagram_story'?'story':$kind,'caption'=>$caption?:($product['name']??''),'media'=>$urls,'product_id'=>$linkedId,'scheduled_at'=>$date,'schedule_id'=>$scheduleId],$_SESSION['user']['username']??'scheduler');
    }
}
